#pragma once
#include "kstationStartupHardwareTask.h"
#include "kstationNativeMidiPump.h"
#include <variant>
namespace kstation {
class NativeStartupHardware final {
 using I=StartupInterruptSetupTask;using T=StartupTimerSetupTask;using P=StartupPwmTask;using S=StartupSerialSetupTask;struct Job{std::variant<I,T,P,S>task;};
public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,2>CodeRanges{{{0x830,0x8ba},{0x9b6,0x9d0}}};bool active()const{return depth_;}void reset(){depth_=0;steps_=0;}uint64_t steps()const{return steps_;}static bool candidate(unsigned at){for(auto r:CodeRanges)if(at>=r.begin&&at<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;if(at==0x830)j.task.emplace<I>();else if(at==0x846)j.task.emplace<T>();else if(at==0x8b4)j.task.emplace<P>(uint8_t(c.reg8(14)));else if(at==0x9b6)j.task.emplace<S>();else return false;if(depth_==jobs_.size())throw std::logic_error("Native K startup hardware capacity");jobs_[depth_++]=j;}
  auto&j=jobs_[depth_-1];if(auto*t=std::get_if<T>(&j.task))if(t->awaiting())t->resume();if(at!=boundary(j))throw std::logic_error("Native K startup hardware boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
  std::visit([&](auto&t){using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,T>)t.advanceBefore(cost,cr,[&](unsigned address,unsigned width,unsigned value){val(c,width==4?c.reg32(1):width==2?c.reg16(1):c.reg8(8));if(width==4)c.write32(int32_t(value),int(address));else if(width==2)c.write16(int16_t(value),int(address));else c.write8(int8_t(value),int(address));});else if constexpr(std::is_same_v<V,P>)t.advanceBefore(cost,cr,[&](unsigned value){val(c,c.reg8(14));c.write8(int8_t(value),0xffff6c);});else t.advanceBefore(cost,cr,[&](unsigned address,unsigned value){val(c,c.reg8(8));c.write8(int8_t(value),int(address));});},j.task);
  if(c.cycles-begin!=cost)throw std::logic_error("Native K startup hardware clocks differ");if(std::visit([](const auto&t){return t.complete();},j.task))--depth_;else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;}
private:static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static bool waiting(const Job&j){auto*t=std::get_if<T>(&j.task);return t&&t->awaiting();}
 static unsigned boundary(const Job&j){return std::visit([](const auto&t)->unsigned{using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,I>)return t.stage()==I::Stage::Return?0x844:0x830+4*t.index()+(t.stage()==I::Stage::Write?2:0);else if constexpr(std::is_same_v<V,T>){static constexpr unsigned a[]={0x846,0x848,0x84a,0x84c,0x84e,0x854,0x858,0x85a,0x860,0x864,0x866,0x868,0x86a,0x86c,0x86e,0x870,0x872,0x874,0x876,0x87c,0x880,0x882,0x884,0x886,0x888,0x88a,0x88c,0x88e,0x894,0x898,0x89a,0x89c,0x89e,0x8a0,0x8a2,0x8a4,0x8a6,0x8ac,0x8ae,0x8b2,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<V,P>)return 0x8b4+2*unsigned(t.stage());else{using Q=S::Stage;switch(t.stage()){case Q::Prepare:return 0x9b6+4*t.index();case Q::Write:return 0x9b8+4*t.index();case Q::Retain:return 0x9c2;case Q::DelayValue:return 0x9c4;case Q::Decrement:return 0x9c8;case Q::Repeat:return 0x9ca;case Q::Restore:return 0x9cc;case Q::Return:return 0x9ce;default:return 0;}}},j.task);}
 static unsigned bytes(const Job&j){if(auto*t=std::get_if<T>(&j.task)){using Q=T::Stage;switch(t->stage()){case Q::BindZeroCounter:case Q::BindPwmPeriod:case Q::BindPanelPeriod:case Q::BindTickPeriod:case Q::BindClock:return 6;case Q::ZeroCounterValue:case Q::PwmPeriodValue:case Q::PanelPeriodValue:case Q::TickPeriodValue:case Q::WriteClock:return 4;default:return 2;}}if(auto*t=std::get_if<S>(&j.task))if(t->stage()==S::Stage::DelayValue)return 4;return 2;}
 static unsigned bus(unsigned at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=unsigned(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;int last=int(c.getPC()+len-1);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);cr.shortCall=3+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);if(auto*t=std::get_if<T>(&j.task))cr.write=bus(t->address(),t->width(),c.writeHistory());else cr.write=1;return cr;}
 static void project(Job&j,Stage1Cpu&c){std::visit([&](const auto&t){using V=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<V,I>){if(t.stage()==I::Stage::Prepare){c.reg8(8)=int8_t(t.value());val(c,c.reg8(8));}else if(t.stage()==I::Stage::Return)midi_projection::ret(c);}else if constexpr(std::is_same_v<V,P>){if(t.stage()==P::Stage::Offset)c.reg8(14)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(14)),0x40,8,false));else if(t.stage()==P::Stage::Return)midi_projection::ret(c);}else if constexpr(std::is_same_v<V,T>){using Q=T::Stage;if(t.address())return;switch(t.stage()){case Q::Return:midi_projection::ret(c);break;case Q::PwmChild:midi_projection::call(c,0x8b4,0x86a,false);break;case Q::BindZeroCounter:case Q::BindPwmPeriod:case Q::BindPanelPeriod:case Q::BindTickPeriod:case Q::BindClock:c.reg32(0)=int32_t(t.value());val(c,c.reg32(0));break;case Q::ZeroCounterValue:case Q::PwmPeriodValue:case Q::PanelPeriodValue:case Q::TickPeriodValue:c.reg16(1)=int16_t(t.value());val(c,c.reg16(1));break;case Q::ClearClock:c.reg32(1)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case Q::PwmValue:c.reg8(14)=int8_t(t.value());val(c,c.reg8(14));break;default:c.reg8(8)=int8_t(t.value());val(c,c.reg8(8));break;}}
 else{using Q=S::Stage;switch(t.stage()){case Q::Prepare:c.reg8(8)=int8_t(t.value());val(c,c.reg8(8));break;case Q::Retain:c.setSP(c.getSP()-2);c.write16(c.reg16(0),int(c.getSP()));val(c,c.reg16(0));c.clockI(2);break;case Q::DelayValue:c.reg16(0)=100;val(c,100);break;case Q::Decrement:{int old=c.reg16(0),v=old-1;val(c,v);if((old&~v)&0x8000)c.ccr|=2;c.reg16(0)=int16_t(v);break;}case Q::Restore:c.reg16(0)=int16_t(c.read16(int(c.getSP())));c.setSP(c.getSP()+2);val(c,c.reg16(0));c.clockI(2);break;case Q::Return:midi_projection::ret(c);break;default:break;}}},j.task);}
 std::array<Job,4>jobs_{};unsigned depth_=0;uint64_t steps_=0;
};
}
